    assert.deepEqual(
      Long.fromBytes([0x12, 0x34, 0x56, 0x78, 0x01, 0x23, 0x45, 0x67]),
      longVal,
    );
    assert.deepEqual(
      Long.fromBytes(
        [0x12, 0x34, 0x56, 0x78, 0x01, 0x23, 0x45, 0x67],
        false,
        false,
      ),
      longVal,
    );
    assert.deepEqual(
      Long.fromBytes(
        [0x67, 0x45, 0x23, 0x01, 0x78, 0x56, 0x34, 0x12],
